// Characterization tests: pin current client-visible behavior, quirks included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { apple: 10, pear: 2.5, tv: 99.99, cheap: 0.3 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})
const create = async (items) => (await post({ items })).json()

test('POST /orders creates order: 201, json, string id, echoed items', async () => {
  const items = [{ sku: 'apple', qty: 2 }]
  const res = await post({ items })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  const body = await res.json()
  assert.deepEqual(Object.keys(body).sort(), ['id', 'items', 'total'])
  assert.equal(typeof body.id, 'string')
  assert.deepEqual(body.items, items)
  assert.equal(body.total, 20)
})

test('ids are sequential strings', async () => {
  const a = await create([{ sku: 'apple', qty: 1 }])
  const b = await create([{ sku: 'apple', qty: 1 }])
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total sums price * qty across items', async () => {
  assert.equal((await create([{ sku: 'apple', qty: 2 }, { sku: 'pear', qty: 4 }])).total, 30)
})

test('total is floored to an integer', async () => {
  assert.equal((await create([{ sku: 'tv', qty: 0 + 0.5 }])).total, 49)
  assert.equal((await create([{ sku: 'cheap', qty: 1 }])).total, 0)
})

test('no discount at exactly 100', async () => {
  assert.equal((await create([{ sku: 'apple', qty: 10 }])).total, 100)
})

test('10% discount applies above 100', async () => {
  assert.equal((await create([{ sku: 'apple', qty: 11 }])).total, 99)
  assert.equal((await create([{ sku: 'apple', qty: 20 }])).total, 180)
})

test('discount is applied before flooring', async () => {
  // 100.5 * 0.9 = 90.45 -> 90
  assert.equal((await create([{ sku: 'apple', qty: 10 }, { sku: 'pear', qty: 0.2 }])).total, 100)
  assert.equal((await create([{ sku: 'tv', qty: 1 }, { sku: 'pear', qty: 1 }])).total, 92)
})

test('GET /orders/:id returns the created order', async () => {
  const created = await create([{ sku: 'pear', qty: 4 }])
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET unknown order returns 200 with error body (not 404)', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('POST validation: 400 for bad bodies', async () => {
  for (const [body, raw] of [
    [{}], [{ items: [] }], [{ items: 'x' }], [null, 'not json'], [null, ''],
  ]) {
    const res = await post(body, raw)
    assert.equal(res.status, 400, JSON.stringify([body, raw]))
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('unknown routes and methods return 404 no route', async () => {
  for (const [method, path] of [
    ['GET', '/'], ['GET', '/orders'], ['PUT', '/orders'], ['DELETE', '/orders/1'],
    ['POST', '/orders/1'], ['GET', '/orders/1/extra'],
  ]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})

test('query string is ignored for routing', async () => {
  const created = await create([{ sku: 'pear', qty: 4 }])
  const res = await fetch(`${base}/orders/${created.id}?x=1`)
  assert.deepEqual(await res.json(), created)
})
EOF
